        ));
        client.set_privacy_options(crate::privacy::PrivacyOptions::default());
        client.set_private_operation_gate(Some(std::sync::Arc::new(deny)));
        assert!(matches!(
            client.run_app_skill(json!({})).await,
            Err(Error::Forbidden)
        ));
    }
}

