        key: &[u8; 32],
        wrapped: &str,
        baseline: u64,
        new_chat: bool,
        existing: &[Value],
        chat: &mut Chat,
        updates: &mpsc::Sender<StreamUpdate>,
        cancel: &CancellationToken,
        generation: u64,
        team_preparation: Option<Value>,
        options: &SendOptions,
        trace: &mut SendTrace,
    ) -> Result<SendOutcome> {
        let turn_scope=AsyncCryptoScope::begin(self)?;
        turn_scope.check_chat(self,id)?;
        let mut observed = Plain::new(SendObservations::default());
        self.active_chat = Some(id.into());
        send(ws, "set_active_chat", json!({"chat_id":id})).await?;
        turn_scope.check_chat(self,id)?;
        // A fresh owner-only snapshot and one-use receipt are bound to this same
        // socket/turn. Cached privacy data cannot authorize inference.
        let team = self.team()?.map(str::to_owned);
        let (snapshot, projects, sender) = if team.is_some() {
            let prepared = Plain::new(team_preparation.ok_or(Error::Protocol)?);
            let projects=Plain::new(prepared["project_candidates"].as_array().ok_or(Error::Protocol)?.clone());
            let sender = required(&prepared, "sender_name")?.to_owned();
            (prepared.into_inner(), projects.into_inner(), sender)
        } else {
            let request_id = uuid::Uuid::new_v4().to_string();
            send(
                ws,
                "personal_send_context_snapshot",
                json!({"request_id":request_id,"purpose":"send","turn_id":turn}),
            )
            .await?;
            let snapshot = Plain::new( tokio::select! {biased;_=cancel.cancelled()=>return Err(Error::Cancelled),r=wait(ws,"personal_send_context_snapshot_result","request_id",&request_id)=>r?});
            if snapshot["success"] != true
                || snapshot["unchanged"] != false
                || text(&snapshot, "turn_id") != turn
            {
                return Err(Error::Protocol);
            }
            required(&snapshot, "receipt_id")?;
            let projects = self.decode_project_candidates(
                snapshot["project_candidates"]
                    .as_array()
                    .ok_or(Error::Protocol)?,
            ).await?;
            (snapshot.into_inner(), projects, "User".into())
        };
        let snapshot=Plain::new(snapshot);
        let projects=Plain::new(projects);
        let sender=Plain::new(sender);
        let master=self.master_capability()?;
        turn_scope.check_chat(self,id)?;
        let memory_snapshot = &snapshot["personal_memories"];
        let mut memories = Plain::new(vec![]);
        let mut memory_metadata = std::collections::BTreeSet::new();
        for raw in memory_snapshot["memories"]
            .as_array()
            .ok_or(Error::Protocol)?
        {
            let plain=Plain::new(master.decrypt_text(required(raw,"encrypted_item_json")?).await?);
            turn_scope.check_chat(self,id)?;
            let data=Plain::new(serde_json::from_str::<Value>(&plain)?);
            if !data.is_object() {
                return Err(Error::Protocol);
            }
            memory_metadata.insert(format!(
                "{}-{}",
                required(raw, "app_id")?,
                required(raw, "item_type")?
            ));
            memories.push(json!({"id":raw["id"],"app_id":raw["app_id"],"item_type":raw["item_type"],"data":&*data}));
        }
        let settings=Plain::new(self.decrypt_optional_with_capability(memory_snapshot,"encrypted_settings",&master).await?);
        turn_scope.check_chat(self,id)?;
        let settings=Plain::new(if settings.is_empty(){json!({})}else{serde_json::from_str::<Value>(&settings)?});
        if !settings.is_object() {
            return Err(Error::Protocol);
        }
        let mut docs = Plain::new(BTreeMap::new());
        let mut chars = 0usize;
        for field in ["rule_documents", "memory_documents"] {
            for value in settings[field].as_array().into_iter().flatten() {
                let doc = text(value, "document");
                let doc_id = text(value, "id");
                if !doc_id.is_empty()
                    && doc_id.len() <= 240
                    && doc.len() <= 24_000
                    && (value["source"].is_null() || value["source"] == "personal")
                {
                    if let Some(mut previous)=docs.insert(doc_id.to_owned(),json!({"id":doc_id,"source":"personal","document":doc})){previous.wipe();}
                }
            }
        }
        let mut selected_docs=Plain::new(vec![]);
        for _ in 0..24{let Some((mut doc_id,mut value))=docs.pop_first()else{break;};doc_id.wipe();chars+=text(&value,"document").len();if chars<=64_000{selected_docs.push(value);}else{value.wipe();}}
        let docs=selected_docs;
        if !docs.is_empty() {
            memory_metadata.insert("openmates-memories".into());
            for doc in docs.iter() {
                memories.push(json!({"id":doc["id"],"app_id":"openmates","item_type":"memories","data":{"document":doc["document"]}}));
            }
        }
        let prepared = Plain::new(if options.pii_detection {
            crate::privacy::prepare(input, &memories, existing)?
        } else {
            crate::privacy::PreparedPrivacy {
                text: input.into(),
                mappings: vec![],
            }
        });
        if cancel.is_cancelled() || self.generation != generation {
            return Err(Error::Cancelled);
        }
        let wait_ai = should_wait_for_ai(&prepared.text, team.as_deref());
        turn_scope.check_chat(self,id)?;
        let project_context=Plain::new(if new_chat||!wait_ai{json!({})}else{self.active_project_context(id,&prepared.text).await?});
        turn_scope.check_chat(self,id)?;
        let recovery = crypto::recovery_keypair(key, id, 1)?;
        let created = now_ms() / 1000;
        let mut encrypted = json!({"client_message_id":message,"chat_id":id,"encrypted_content":crypto::encrypt_combined(&prepared.text,key)?,"encrypted_sender_name":crypto::encrypt_combined(&sender,key)?,"role":"user","created_at":created,"updated_at":created});
        if !prepared.mappings.is_empty(){let encoded=Plain::new(serde_json::to_string(&prepared.mappings)?);encrypted["encrypted_pii_mappings"]=json!(crypto::encrypt_combined(&encoded,key)?);}
        let mut inference = Plain::new(json!({"chat_id":id,"client_capabilities":[],"is_incognito":false,"message":{"message_id":message,"chat_id":id,"role":"user","sender_name":"User","status":"sent","content":prepared.text,"created_at":created,"chat_has_title":!new_chat},"turn_id":turn,"recovery_public_key":recovery.public_key,"chat_key_version":1,"custom_memory_documents":[],"app_settings_memories_metadata":memory_metadata,"project_focus_candidates":projects.as_slice()}));
        if options.task_update_jobs {
            inference["client_capabilities"] = json!(["task_update_jobs"]);
        }
        let (active_focus, mut focus_state) = self.current_focus_state(id, key)?;
        inference["active_focus_id"] = json!(active_focus);
        inference["focus_phase_state"] = focus_state.clone();
        if let Some(context) = project_context.as_object() {
            for (k, v) in context {
                inference[k] = v.clone();
            }
        }
        if new_chat {
            inference["encrypted_chat_key"] = json!(wrapped)
        }
        if let Some(rows)=self.history.get(id){
            let mut history=Plain::new(vec![]);
            for row in rows{
                let sender=Plain::new(decrypt_optional(row,"encrypted_sender_name",key)?);
                let content=Plain::new(decrypt_optional(row,"encrypted_content",key)?);
                history.push(json!({"message_id":row.get("client_message_id").or_else(||row.get("message_id")).or_else(||row.get("id")),"chat_id":id,"role":row["role"],"sender_name":sender.as_str(),"content":content.as_str(),"created_at":row["created_at"]}));
            }
            if !history.is_empty(){inference["message_history"]=json!(history.as_slice());}
        }
        if let Some(team) = &team {
            inference["team_id"] = json!(team);
            let mut envelope = encrypted.clone();
            envelope["message_id"] = json!(message);
            inference["message"].wipe();
            inference["message"] = envelope;
            let mut prior_value=Plain::new(inference.as_object_mut().ok_or(Error::Protocol)?.remove("message_history"));
            let prior=Plain::new(match prior_value.take(){Some(Value::Array(rows))=>rows,Some(mut other)=>{other.wipe();vec![]},None=>vec![]});
            if !wait_ai {
                let replacement=Plain::new(json!({"chat_id":id,"team_id":team,"turn_id":turn,"is_incognito":false,"message":inference["message"],"recovery_public_key":recovery.public_key,"chat_key_version":1}));
                inference.wipe();*inference=replacement.into_inner();
                if new_chat {
                    inference["encrypted_chat_key"] = json!(wrapped)
                }
            }
            if wait_ai {
                let mut history = prior;
                history.push(json!({"role":"user","content":prepared.text,"sender_name":sender.as_str(),"created_at":created}));
                inference["team_ai_invocation"] = json!({"history":history.as_slice()});
                inference["message_history"] = json!(history.as_slice());
            }
        }
        let mut payload=Plain::new(json!({"protocol_version":1,"chat_id":id,"turn_id":turn,"message_id":message,"chat_key_version":1,"encrypted_chat_key":wrapped,"recovery_public_key":recovery.public_key,"expected_messages_v":baseline,"encrypted_user_message":encrypted}));
        payload["inference_request"]=inference.into_inner();
        if let Some(team) = &team {
            payload["team_id"] = json!(team)
        } else {
            payload["privacy_receipt_id"] = snapshot["receipt_id"].clone();
            payload["privacy_generation"] = snapshot["privacy_generation"].clone();
        }
        if new_chat{payload["encrypted_chat_metadata"]=self.turn_chat_metadata(id,input,key,wrapped,created,team.as_deref(),wait_ai,options).await?;turn_scope.check_chat(self,id)?;}
        if cancel.is_cancelled() || self.generation != generation {
            return Err(Error::Cancelled);
        }
        turn_scope.check_chat(self,id)?;
        if let Some(observation) = &self.scoped_send_observation {
            let remaining=MAX_SCOPED_SAVED_SEND_QUARANTINE_BYTES.checked_sub(self.scoped_send_quarantine_bytes).ok_or(Error::Conflict)?;
            let bytes=scoped_admission_size(&payload,remaining)?;
            let mut observation=observation.lock().map_err(|_|Error::Cancelled)?;
            observation.admission_bytes=bytes;
            observation.admission=Some(Plain::new((*payload).clone()));
            // Team preview is already an original remote saved effect.
            if team.is_some() { observation.attempted=true; }
        }
        if team.is_some() {
            self.stage_team_preview(ws, id, message, &prepared.text, Some(&chat.title))
                .await?;
        }
        // Bind the UI before dispatch. Once submission starts, an interrupted
        // transport has an ambiguous commit outcome and must not trigger resend.
        self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Started {
                chat_id: id.into(),
                message_id: message.into(),
                expects_reply: wait_ai,
            }).await?;
        self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Submitted {
                chat_id: id.into(),
                message_id: message.into(),
            }).await?;
        // UI delivery can await a bounded host queue. Recheck the same
        // turn/owner generation and cancellation fence after that suspension,
        // before admission can cause a saved message or inference effect.
        if cancel.is_cancelled() || self.generation != generation {
            return Err(Error::Cancelled);
        }
        turn_scope.check_chat(self,id)?;
        // Mark before the transport await: a failed write is an uncertain
        // original attempt, never proof that a new turn may be replayed.
        if let Some(observation) = &self.scoped_send_observation {
            observation.lock().map_err(|_| Error::Cancelled)?.attempted = true;
        }
        transport::send_plaintext(ws,"chat_turn_admit",payload.into_inner()).await?;
        let mut confirmed = false;
        let mut admitted = false;
        let mut admission_notified = false;
        let mut version = baseline + 1;
        let mut content = Plain::new(String::new());
        let mut thinking = Plain::new(String::new());
        let mut task_id = String::new();
        let mut final_frame=Plain::new(None::<Value>);
        let deadline = crate::platform::time::Instant::now()
            + Duration::from_millis(options.response_timeout_ms.unwrap_or(600_000));
        let mut queued=Plain::new(None::<Value>);
        let mut deferred=Plain::new(std::collections::VecDeque::new());
        let mut consent_requests = std::collections::HashSet::new();
        let mut streamed_embeds=Plain::new(BTreeMap::new());
        let mut checkpoints=Plain::new(vec![]);
        let mut generated_header=Plain::new(Value::Null);
        let mut recovery_outputs=Plain::new(BTreeMap::new());
        loop {
            trace.phase = SendPhase::StreamReceive;
            let event = if let Some(event) = deferred.pop_front() {
                event
            } else {
                tokio::select! {biased;_=cancel.cancelled()=>{if !task_id.is_empty(){let _=send(ws,"cancel_ai_task",json!({"task_id":task_id,"chat_id":id})).await;}return Err(Error::Cancelled)},r=crate::platform::time::timeout_at(deadline,receive(ws))=>r.map_err(|_|Error::Offline)??}
            };
            let (kind,p)=event;let p=Plain::new(p);
            trace.phase = SendPhase::FrameValidation;
            turn_scope.check_chat(self,id)?;
            if self.generation != generation {
                return Err(Error::Cancelled);
            }
            if kind == "chat_turn_preflight_ack" && text(&p, "turn_id") == turn {
                required(&p, "preflight_id")?;
                admitted = true;
                if let Some(v) = p["committed_messages_v"].as_u64() {
                    version = v
                }
            }
            if kind == "chat_message_confirmed"
                && text(&p, "chat_id") == id
                && text(&p, "message_id") == message
            {
                confirmed = true;
                if let Some(v) = p["new_messages_v"].as_u64() {
                    version = v
                }
            }
            if (admitted || confirmed) && !admission_notified {
                admission_notified = true;
                self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Admitted {
                        chat_id: id.into(),
                        message_id: message.into(),
                    }).await?;
            }
            let same = belongs_to_turn(&p, id, message, turn);
            if same && !text(&p, "task_id").is_empty() {
                task_id = text(&p, "task_id").into();
            }
            if owns_metadata(&p, id, message, turn, &task_id) {
                observed.capture_owned(&kind, &p)?;
            }
            if kind == "task_update_jobs_available"
                && owns_metadata(&p, id, message, turn, &task_id)
            {
                observed.capture_jobs(&p, id)?;
            }
            if kind == "message_queued" && same {
                queued.wipe();*queued=Some(p.clone());
            }
            if let Some(frame) = &*queued
                && admitted
                && confirmed
            {
                let mode = match frame["queue_mode"].as_str() {
                    Some("follow_up") => SendQueueMode::FollowUp,
                    Some("steer") => SendQueueMode::Steer,
                    _ => return Err(Error::Protocol),
                };
                let revision = frame["queue_revision"]
                    .as_u64()
                    .filter(|v| *v > 0)
                    .ok_or(Error::Protocol)?;
                chat.messages.push(Message {
                    id: message.into(),
                    role: "user".into(),
                    content: crate::privacy::restore(&prepared.text, &prepared.mappings)?,
                    sender: sender.clone(),
                    ..Message::default()
                });
                self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Status(
                        "Message saved and queued for the active assistant turn.".into(),
                    )).await?;
                let mut outcome = Plain::new(observed.into_inner().finish(chat.clone(), message, None, SendStatus::Queued));
                outcome.queue_mode = Some(mode);
                outcome.queue_revision = Some(revision);
                turn_scope.check_chat(self,id)?;
                return Ok(outcome.into_inner());
            }
            trace.observe_discovery(&kind, &p);
            // Discovery is owner-global and can precede the final frame. It is
            // still validated, but never authorizes this turn's completion.
            super::recovery::capture(&kind, &p, &mut recovery_outputs)?;
            trace.phase = SendPhase::FrameValidation;
            capture_artifact(
                &kind,
                &p,
                id,
                &task_id,
                &mut streamed_embeds,
                &mut checkpoints,
            )?;
            if kind == "ai_typing_started" && same {
                generated_header.wipe();*generated_header=p.clone();
            }
            if ["focus_mode_activated", "focus_phases_updated"].contains(&kind.as_str())
                && text(&p, "chat_id") == id
                && (text(&p, "task_id").is_empty() || text(&p, "task_id") == task_id)
            {
                self.persist_focus_event(ws, &kind, &p, id, key, &mut focus_state)
                    .await?;
            }
            if kind == "project_focus_catalog_requested"
                && text(&p, "chat_id") == id
                && p.get("team_id").and_then(Value::as_str) == team.as_deref()
            {
                let project = required(&p, "project_id")?;
                if !projects.iter().any(|v| text(v, "project_id") == project) {
                    return Err(Error::Forbidden);
                }
                let focuses=Plain::new(match self.project_routing_catalog(project).await{Ok(focuses)=>Some(focuses),Err(error @ (Error::Cancelled|Error::Expired|Error::Authentication|Error::Forbidden))=>return Err(error),Err(_)=>None});
                turn_scope.check_chat(self,id)?;
                transport::send_plaintext(ws,"project_focus_catalog_result",json!({"chat_id":id,"request_id":required(&p,"request_id")?,"project_id":project,"focuses":&*focuses})).await?;
            }
            if kind == "sub_chat_confirmation_required"
                && text(&p, "chat_id") == id
                && !task_id.is_empty()
                && text(&p, "task_id") == task_id
                && consent_requests.insert(format!("subchat:{task_id}"))
            {
                deferred.extend(
                    self.subchat_consent(
                        ws,
                        &p,
                        id,
                        &task_id,
                        updates,
                        cancel,
                        options.sub_chat_consent,
                    )
                    .await?,
                );
            }
            if kind == "request_app_settings_memories"
                && admit_memory_request(&p, id, message, &mut consent_requests)
            {
                let (frames, record) = self
                    .memory_consent(
                        ws,
                        &p,
                        id,
                        message,
                        key,
                        &memories,
                        updates,
                        cancel,
                        options.memory_consent,
                    )
                    .await?;
                deferred.extend(frames);
                if observed.memories.len() >= 64 {
                    return Err(Error::Protocol);
                }
                observed.memories.push(record);
            }
            if kind == "ai_task_initiated"
                && text(&p, "chat_id") == id
                && text(&p, "user_message_id") == message
            {
                task_id = text(&p, "task_id").into()
            }
            if kind == "thinking_chunk"
                && text(&p, "chat_id") == id
                && !task_id.is_empty()
                && text(&p, "task_id") == task_id
            {
                thinking.push_str(text(&p, "content"));
                self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Content {
                        content: content.clone(),
                        thinking: thinking.clone(),
                        mate: String::new(),
                    }).await?;
            }
            if same && (kind == "ai_message_update" || kind == "ai_background_response_completed") {
                if let Some(full) = p
                    .get("full_content_so_far")
                    .or_else(|| p.get("full_content"))
                    .and_then(Value::as_str)
                {
                    replace_text(&mut content,full.into())
                }
                self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Content {
                        content: content.clone(),
                        thinking: thinking.clone(),
                        mate: text(&p, "category").into(),
                    }).await?;
                if (p["is_final_chunk"] == true || kind == "ai_background_response_completed")
                    && !has_continuation(&p)
                {
                    trace.final_seen = true;
                    if p["recovery_protocol_version"] != 1 || text(&p, "recovery_turn_id") != turn {
                        return Err(Error::Protocol);
                    }
                    required(&p, "recovery_job_id")?;
                    required(&p, "message_id")?;
                    final_frame.wipe();*final_frame=Some(p.clone());
                }
            }
            if same
                && ["ai_task_error", "ai_error", "queued_handoff_paused"].contains(&kind.as_str())
            {
                return Err(Error::Protocol);
            }
            if !wait_ai && admitted && confirmed {
                chat.messages.push(Message {
                    id: message.into(),
                    role: "user".into(),
                    content: input.into(),
                    sender: sender.clone(),
                    ..Message::default()
                });
                self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Completed {
                        chat_id: id.into(),
                        message_id: message.into(),
                        content: String::new(),
                    }).await?;
                turn_scope.check_chat(self,id)?;
                let outcome=Plain::new(observed.into_inner().finish(chat.clone(),message,None,SendStatus::Completed));turn_scope.check_chat(self,id)?;return Ok(outcome.into_inner());
            }
            // Only the admitted current-turn final frame opens the existing
            // authoritative claim path. Claim identity, sealed owner/turn/key
            // binding and durable terminal ACK remain the success authority.
            if final_frame.is_some() && admitted && confirmed {
                break;
            }
        }
        // Finish the trailing artifact frames before committing success.
        let drain_deadline = crate::platform::time::Instant::now() + Duration::from_secs(2);
        while crate::platform::time::Instant::now() < drain_deadline {
            trace.phase = SendPhase::TrailingFrames;
            let event = if let Some(event) = deferred.pop_front() {
                Some(Ok(event))
            } else {
                crate::platform::time::timeout(Duration::from_millis(250), receive(ws))
                    .await
                    .ok()
            };
            match event {
                Some(Ok((kind, p))) => {
                    let p=Plain::new(p);turn_scope.check_chat(self,id)?;
                    if owns_metadata(&p, id, message, turn, &task_id) {
                        observed.capture_owned(&kind, &p)?;
                    }
                    if kind == "task_update_jobs_available"
                        && owns_metadata(&p, id, message, turn, &task_id)
                    {
                        observed.capture_jobs(&p, id)?;
                    }
                    trace.observe_discovery(&kind, &p);
                    super::recovery::capture(&kind, &p, &mut recovery_outputs)?;
                    trace.phase = SendPhase::TrailingFrames;
                    capture_artifact(
                        &kind,
                        &p,
                        id,
                        &task_id,
                        &mut streamed_embeds,
                        &mut checkpoints,
                    )?;
                }
                Some(Err(e)) => return Err(e),
                None => break,
            }
        }
        trace.phase = SendPhase::FrameValidation;
        let final_frame=Plain::new(final_frame.take().ok_or(Error::Protocol)?);
        let job = required(&final_frame, "recovery_job_id")?;
        let assistant_id = required(&final_frame, "message_id")?;
        trace.phase = SendPhase::Claim;
        turn_scope.check_chat(self,id)?;
        send(ws,"recovery_job_claim",json!({"protocol_version":1,"job_id":job,"request_id":uuid::Uuid::new_v4().to_string()})).await?;
        let claim=Plain::new(tokio::select! {biased;_=cancel.cancelled()=>return Err(Error::Cancelled),r=wait(ws,"recovery_job_claimed","job_id",job)=>r?});
        turn_scope.check_chat(self,id)?;
        if text(&claim, "chat_id") != id
            || text(&claim, "turn_id") != turn
            || text(&claim, "assistant_message_id") != assistant_id
            || claim["chat_key_version"] != 1
        {
            return Err(Error::Protocol);
        }
        if text(&claim, "state") == "TERMINAL" {
            // Read the canonical ciphertext rather than treating transient text
            // as proof that another device completed the same job.
            let selected_outputs=Self::select_turn_outputs(recovery_outputs,id,turn);
            trace.phase = SendPhase::ReplayArtifacts;
            self.replay_outputs(ws, &selected_outputs, Some((id, key)))
                .await?;
            self.persist_stream_artifacts(
                ws,
                id,
                assistant_id,
                key,
                &task_id,
                &streamed_embeds,
                &checkpoints,
            )
            .await?;
            trace.phase = SendPhase::Metadata;
            let chat = Plain::new(self.open_chat_live(id).await?);
            if !chat.messages.iter().any(|m| m.id == assistant_id) {
                return Err(Error::Protocol);
            }
            let content=Plain::new(chat.messages.iter().find(|m|m.id==assistant_id).ok_or(Error::Protocol)?.content.clone());
            trace.phase = SendPhase::TaskFinalize;
            self.finish_task_jobs(ws, &mut observed, id, message, key, cancel, options)
                .await?;
            self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Completed {
                    chat_id: id.into(),
                    message_id: assistant_id.into(),
                    content:content.into_inner(),
                }).await?;
            turn_scope.check_chat(self,id)?;
            let outcome=Plain::new(observed.into_inner().finish(chat.into_inner(),message,Some(assistant_id),SendStatus::Completed));turn_scope.check_chat(self,id)?;return Ok(outcome.into_inner());
        }
        if text(&claim, "state") != "LEASED"
            || claim["lease_generation"].as_u64().is_none_or(|v| v < 1)
        {
            return Err(Error::Protocol);
        }
        trace.phase = SendPhase::Decode;
        let envelope=Plain::new(serde_json::from_str::<Value>(required(&claim,"sealed_payload")?)?);
        let owner = text(&self.user, "id");
        let owner = if owner.is_empty() {
            required(&self.user, "user_id")?
        } else {
            owner
        };
        let identity = crypto::RecoveryIdentity {
            owner_id: owner.into(),
            chat_id: id.into(),
            turn_id: turn.into(),
            job_id: job.into(),
            assistant_message_id: assistant_id.into(),
            key_version: 1,
        };
        let recovered=Plain::new(super::completion_recovery::decode_main_completion(&envelope,key,&identity)?);
        observed.capture_owned("recovered_completion", &recovered)?;
        replace_text(&mut content,required(&recovered,"content")?.into());
        let created = final_frame["created_at"].as_u64().ok_or(Error::Protocol)?;
        let encrypted = super::completion_recovery::encrypt_main_assistant(
            &recovered,
            &identity,
            created,
            Some(message),
            key,
        )?;
        // Consent/system writes and other Team members can advance history
        // after admission. Read the current authorized key/version before the
        // terminal transaction; never guess its expected version.
        trace.phase = SendPhase::Metadata;
        let path = self.scoped("/v1/chats/metadata/batch")?;
        let current = self
            .request(Method::POST, &path, Some(json!({"chat_ids":[id]})))
            .await?;
        let row = current["chats"]
            .as_array()
            .ok_or(Error::Protocol)?
            .iter()
            .find(|r| text(r, "id") == id)
            .ok_or(Error::Forbidden)?
            .clone();
        let wrapping = self.wrapping_capability().await?;
        if self.chat_key_with_capability(&row,&wrapping).await?.as_ref() != key {
            return Err(Error::Crypto);
        }
        let latest = row["messages_v"].as_u64().ok_or(Error::Protocol)?;
        if latest < version {
            return Err(Error::Protocol);
        }
        version = latest;
        self.insert_chat_row(id.into(), row);
        if cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        trace.phase = SendPhase::Persist;
        turn_scope.check_chat(self,id)?;
        transport::send_plaintext(ws,"recovery_job_persist",json!({"protocol_version":1,"job_id":job,"lease_token":required(&claim,"lease_token")?,"lease_generation":claim["lease_generation"],"expected_messages_v":version,"encrypted_assistant_message":encrypted})).await?;
        wait_terminal_persisted(ws, job).await?;
        turn_scope.check_chat(self,id)?;
        let selected_outputs=Self::select_turn_outputs(recovery_outputs,id,turn);
        trace.phase = SendPhase::ReplayArtifacts;
        self.replay_outputs(ws, &selected_outputs, Some((id, key)))
            .await?;
        let artifacts = self
            .persist_stream_artifacts(
                ws,
                id,
                assistant_id,
                key,
                &task_id,
                &streamed_embeds,
                &checkpoints,
            )
            .await?;
        if new_chat && !text(&generated_header, "chat_title").is_empty() {
            trace.phase = SendPhase::Metadata;
            let title = text(&generated_header, "chat_title");
            let mut metadata = json!({"chat_id":id,"encrypted_chat_key":wrapped,"encrypted_title":crypto::encrypt_combined(title,key)?});
            if let Some(team) = &team {
                metadata["team_id"] = json!(team)
            }
            send(ws, "encrypted_chat_metadata", metadata).await?;
            wait(ws, "encrypted_metadata_stored", "chat_id", id).await?;
            chat.title = title.into();
        }
        trace.phase = SendPhase::TaskFinalize;
        chat.messages.push(Message {
            id: message.into(),
            role: "user".into(),
            content: crate::privacy::restore(&prepared.text, &prepared.mappings)?,
            sender: sender.clone(),
            ..Message::default()
        });
        chat.messages.push(Message {
            id: assistant_id.into(),
            role: "assistant".into(),
            content: crate::privacy::restore(&content, &prepared.mappings)?,
            thinking: crate::privacy::restore(
                recovered["thinking_content"].as_str().unwrap_or(""),
                &prepared.mappings,
            )?,
            sender: "Assistant".into(),
            embeds: artifacts,
        });
        chat.category = text(&recovered, "category").into();
        self.finish_task_jobs(ws, &mut observed, id, message, key, cancel, options)
            .await?;
        let content = crate::privacy::restore(&content, &prepared.mappings)?;
        self.deliver_turn_update(&turn_scope,id,updates,cancel,StreamUpdate::Completed {
                chat_id: id.into(),
                message_id: assistant_id.into(),
                content,
            }).await?;
        turn_scope.check_chat(self,id)?;
        let outcome=Plain::new(observed.into_inner().finish(chat.clone(),message,Some(assistant_id),SendStatus::Completed));
        turn_scope.check_chat(self,id)?;
        Ok(outcome.into_inner())
    }
    #[allow(clippy::too_many_arguments)]
    async fn finish_task_jobs(
        &mut self,
        ws: &mut Socket,
        observed: &mut SendObservations,
        id: &str,
        message: &str,
        key: &[u8; 32],
        cancel: &CancellationToken,
        options: &SendOptions,
    ) -> Result<()> {
        if options.task_update_jobs {
            let done = self
                .persist_task_jobs(
                    ws,
                    &observed.jobs,
                    &observed.events,
                    Some((id, key, message)),
                    cancel,
                )
                .await?;
            observed.jobs.retain(|id, _| !done.contains(id));
        }
        Ok(())
    }
}
async fn wait_terminal_persisted(ws: &mut Socket, job: &str) -> Result<()> {
    let persisted = wait(ws, "recovery_job_persisted", "job_id", job).await?;
    // All canonical success branches, including idempotent retries, carry this
    // state. The idempotent terminal branch may omit committed_messages_v.
    if persisted["state"] != "TERMINAL" {
        return Err(Error::Protocol);
    }
    Ok(())
}
fn owns_metadata(p: &Value, chat: &str, user: &str, turn: &str, task: &str) -> bool {
    text(p, "chat_id") == chat
        && ["turn_id", "recovery_turn_id"].iter().all(|key| {
            p.get(*key)
                .and_then(Value::as_str)
                .is_none_or(|id| id == turn)
        })
        && p.get("user_message_id")
            .and_then(Value::as_str)
            .is_none_or(|id| id == user)
        && (belongs_to_turn(p, chat, user, turn)
            || (text(p, "message_id") == user
                && p.get("turn_id")
                    .and_then(Value::as_str)
                    .is_none_or(|id| id == turn))
            || (!task.is_empty()
                && text(p, "task_id") == task
                && p.get("user_message_id")
                    .and_then(Value::as_str)
                    .is_none_or(|id| id == user)
                && p.get("turn_id")
                    .and_then(Value::as_str)
                    .is_none_or(|id| id == turn)))
}
fn belongs_to_turn(p: &Value, chat: &str, user: &str, turn: &str) -> bool {
    text(p, "chat_id") == chat
        && text(p, "user_message_id") == user
        && p.get("recovery_turn_id")
            .and_then(Value::as_str)
            .is_none_or(|v| v == turn)
}
fn has_continuation(p: &Value) -> bool {
    [
        "waiting_for_skill_completion",
        "awaiting_async_skill_continuation",
        "awaiting_focus_mode_continuation",
        "awaiting_sub_chats_completion",
        "is_project_operation_pending",
    ]
    .into_iter()
    .any(|k| p[k] == true)
}
